function toast(message){ const b=$('#toast'); b.textContent=message; b.classList.remove('hidden'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>b.classList.add('hidden'),2800); }
async function api(url, options={}){
  const opt={...options,headers:{...(options.headers||{})}};
  if(options.body && !(options.body instanceof FormData) && !opt.headers['Content-Type']) opt.headers['Content-Type']='application/json';
  if(token) opt.headers.Authorization=`Bearer ${token}`;
  const r=await fetch(url,opt); const data=await r.json().catch(()=>({})); if(!r.ok) throw new Error(data.error||'حدث خطأ'); return data;
}
function syncSocketAuth(){if(token)socket.emit('session:auth',{token});}
socket.on('connect',syncSocketAuth);
socket.on('notification:new',n=>{if(!me)return;socialSummary=socialSummary||{};socialSummary.notifications=[n,...(socialSummary.notifications||[])];const unread=(socialSummary.notifications||[]).filter(x=>!x.readAt).length+(socialSummary.requests||[]).length;$('#notificationCount').textContent=unread;$('#notificationCount').classList.toggle('hidden',!unread);if(!$('#socialModal')?.classList.contains('hidden'))renderNotificationList(socialSummary.notifications);toast(n.text||'تنبيه جديد');});

async function init(){
  try{
    initLanguage();
    rooms=await api('/api/rooms'); renderRooms(); fillRoomSelect();
    if(token){ try{me=await api('/api/me');syncSocketAuth();}catch{logout(false);} }
    updateAuthUI(); await loadChannelHome(); await loadFeed(); await loadPoliticalNews();
  }catch(e){ $('#feed').innerHTML=`<div class="card errorCard">${esc(e.message)}</div>`; }
}
function canManageRoom(r){return !!me&&r.ownerUserId===me.id;}
const canModerateCurrentRoom=()=>!!me&&!!currentRoom&&currentRoomPower.canModerate&&!currentRoomPower.banned;
async function refreshRooms(){rooms=await api('/api/rooms');renderRooms();fillRoomSelect();}
function liveScore(live){return (live?.viewerCount||0)*3+(live?.likeCount||0)*2+(live?.broadcasters?.length||0);}
function t(key){const lang=localStorage.getItem('uiLang')||'ar';return (uiText[lang]||uiText.en)[key]||uiText.ar[key]||key;}
function renderLiveTicker(){const liveRooms=rooms.filter(r=>r.live?.active).sort((a,b)=>liveScore(b.live)-liveScore(a.live));const wrap=$('#liveTicker');if(!wrap)return;wrap.classList.toggle('hidden',!liveRooms.length);wrap.innerHTML=liveRooms.length?`<div class="tickerHead"><b>${esc(t('hot'))}</b><span>${liveRooms.length} بث مباشر</span></div><div class="tickerRail">${liveRooms.map((r,i)=>{const l=r.live||{},host=l.displayName||'مضيف',guests=Math.max(0,(l.broadcasters?.length||1)-1);return `<button class="liveTickerItem ${i===0?'hot':''}" data-room="${esc(r.id)}"><span class="tickerRank">${i===0?'🔥 الأبرز':'● LIVE'}</span><strong>${esc(r.name)}</strong><small class="tickerTopic">${esc(l.topicTitle||'حوار مباشر')}</small><small>المضيف: ${esc(host)} · ${guests} مشارك · ${l.viewerCount||0} مشاهد</small><em>ادخل الغرفة وشاهد الحوار</em></button>`}).join('')}</div>`:'';wrap.querySelectorAll('.liveTickerItem').forEach(b=>b.onclick=async()=>{await selectRoom(b.dataset.room);if(activeLive&&!liveBroadcaster&&!liveWatching)watchLive();});}
async function loadChannelHome(){await Promise.all([loadChannelMeta(),loadLiveChannels(),loadChannels(true)]);}
async function loadChannelMeta(){try{channelMeta=await api('/api/channels/meta');$('#channelRegion').innerHTML='<option value="">كل المناطق</option>'+channelMeta.regions.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('');$('#channelCountry').innerHTML='<option value="">كل الدول</option>'+channelMeta.countries.map(c=>`<option value="${esc(c.id)}">${esc(c.flag||'')} ${esc(c.nameAr||c.nameEn)}</option>`).join('');$('#channelLanguage').innerHTML='<option value="">كل اللغات</option>'+channelMeta.languages.map(l=>`<option value="${esc(l.id)}">${esc(l.nameAr||l.nameEn)}</option>`).join('');}catch(e){$('#channelGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`;}}
function channelBadge(c){return `${c.country?.flag||''} ${c.country?.nameAr||c.country?.nameEn||'عالمي'} · ${c.language?.nameAr||c.language?.nameEn||''}`;}
function channelThumb(c){return c.live?.thumbnail||c.logoUrl||'';}
function channelCard(c){const thumb=channelThumb(c),live=c.live?.isLive,playable=live||c.youtubeChannelId||c.manualVideoId;return `<article class="channelCard ${live?'isLive':''}" data-channel="${esc(c.id)}">${thumb?`<img loading="lazy" src="${esc(thumb)}" alt="${esc(c.name)}">`:`<div class="channelLogo">${esc((c.name||'ق').slice(0,1))}</div>`}<div class="channelBody"><span class="channelType">${live?'LIVE':playable?'بث رسمي':'قناة إخبارية'}</span><b>${esc(c.name)}</b><small>${esc(channelBadge(c))}</small>${c.live?.title?`<p>${esc(c.live.title)}</p>`:''}<div class="channelActions"><button class="watchChannel primary" data-channel="${esc(c.id)}">${playable?'شاهد الآن':'زيارة القناة'}</button><button class="discussChannel" data-channel="${esc(c.id)}">ناقش البث</button>${me?`<button class="followChannel" data-channel="${esc(c.id)}" data-followed="${c.followed?'1':'0'}">${c.followed?'إلغاء المتابعة':'متابعة'}</button>`:''}</div></div></article>`;}
async function loadLiveChannels(){const rail=$('#channelLiveRail');if(!rail)return;try{const data=await api('/api/channels/live?limit=12');const list=data.channels||[];rail.innerHTML=list.length?list.map(channelCard).join(''):'<div class="empty">لا توجد قنوات مباشرة مؤكدة في الكاش الآن. أضف YOUTUBE_API_KEY أو manual video ID لتفعيل المباشر.</div>';wireChannelCards(rail);}catch(e){rail.innerHTML=`<div class="empty">${esc(e.message)}</div>`;}}
async function loadChannels(reset=false){if(channelState.loading)return;channelState.loading=true;try{if(reset){channelState.page=1;$('#channelGrid').innerHTML='';}const params=new URLSearchParams({page:channelState.page,limit:channelState.limit});const q=$('#channelSearch')?.value.trim()||'',region=$('#channelRegion')?.value||'',country=$('#channelCountry')?.value||'',language=$('#channelLanguage')?.value||'';if(q)params.set('search',q);if(region)params.set('region',region);if(country)params.set('country',country);if(language)params.set('language',language);if(channelState.liveOnly)params.set('live','true');const data=await api(`/api/channels?${params}`);channelState.total=data.total||0;const grid=$('#channelGrid');grid.insertAdjacentHTML('beforeend',(data.channels||[]).map(channelCard).join('')||(reset?'<div class="empty">لا توجد قنوات مطابقة.</div>':''));$('#channelTotal').textContent=`${channelState.total} قناة`;channelState.page+=1;$('#loadMoreChannels').classList.toggle('hidden',grid.querySelectorAll('.channelCard').length>=channelState.total);wireChannelCards(grid);}catch(e){$('#channelGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`;}finally{channelState.loading=false;}}
function wireChannelCards(root=document){root.querySelectorAll('.watchChannel').forEach(btn=>btn.onclick=()=>openChannelPlayer(btn.dataset.channel));root.querySelectorAll('.discussChannel').forEach(btn=>btn.onclick=()=>discussChannel(btn.dataset.channel));root.querySelectorAll('.followChannel').forEach(btn=>btn.onclick=()=>toggleChannelFollow(btn));}
async function openChannelPlayer(channelId){try{const data=await api(`/api/channels/${encodeURIComponent(channelId)}/player`),c=data.channel;mediaPlayerState={mode:'expanded',channel:c,videoId:data.videoId||'',embedUrl:data.embedUrl||'',youtubeUrl:data.youtubeUrl||data.fallbackUrl||'',playerType:data.playerType||'',muted:false};$('#theaterChannelName').textContent=c.name;$('#theaterChannelMeta').textContent=channelBadge(c);$('#theaterLiveTitle').textContent=c.live?.title||c.name;$('#theaterFallback').textContent=data.playable?(data.playerType==='official-page'?'يتم تشغيل البث من صفحة القناة الرسمية داخل الموقع.':'يتم تشغيل البث داخل الموقع عبر مشغل YouTube الرسمي.'):'هذا البث غير متاح للمشاهدة داخل الموقع';$('#openYoutubeBtn').href=mediaPlayerState.youtubeUrl||c.websiteUrl||'#';$('#openYoutubeBtn').textContent=data.playable?'فتح المصدر الرسمي':'زيارة القناة الرسمية';renderChannelPlayer();}catch(e){toast(e.message);}}
function normalizedEmbedUrl(src){if(!src)return '';const url=new URL(src,location.origin);if(url.hostname.includes('youtube.com')||url.hostname.includes('youtube-nocookie.com')){url.searchParams.set('origin',location.origin);url.searchParams.set('enablejsapi','1');url.searchParams.set('playsinline','1');}return url.toString();}
function youtubeEmbedUrl(){return normalizedEmbedUrl(mediaPlayerState.embedUrl);}
function renderChannelPlayer(){const theater=$('#channelTheater'),mini=$('#miniChannelPlayer'),frame=$('#youtubeFrame'),miniFrame=$('#miniYoutubeFrame');clearTimeout(channelPlayerFallbackTimer);theater.classList.toggle('hidden',mediaPlayerState.mode!=='expanded');mini.classList.toggle('hidden',mediaPlayerState.mode!=='mini');if(mediaPlayerState.mode==='closed'){frame.innerHTML='';miniFrame.innerHTML='';return;}const holder=mediaPlayerState.mode==='mini'?miniFrame:frame,src=youtubeEmbedUrl();let iframe=document.getElementById('channelYoutubeIframe');if(!src){holder.innerHTML='<div class="empty channelPlayerMessage">هذا البث غير متاح للمشاهدة داخل الموقع</div>';return;}if(!iframe||iframe.dataset.src!==src){iframe=document.createElement('iframe');iframe.id='channelYoutubeIframe';iframe.dataset.src=src;iframe.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';iframe.referrerPolicy='strict-origin-when-cross-origin';iframe.allowFullscreen=true;iframe.src=src;}holder.innerHTML='';holder.appendChild(iframe);if(mediaPlayerState.playerType==='channel-live'&&mediaPlayerState.mode==='expanded')channelPlayerFallbackTimer=setTimeout(()=>{if(mediaPlayerState.mode==='expanded'&&document.getElementById('channelYoutubeIframe')?.dataset.src===src&&!holder.querySelector('.channelPlayerMessage'))holder.insertAdjacentHTML('beforeend','<div class="channelPlayerMessage">إذا بقيت الشاشة فارغة فالقناة لا تبث مباشرًا الآن أو تمنع التضمين داخل المواقع.</div>');},4500);$('#miniChannelName').textContent=mediaPlayerState.channel?.name||'';}
function setChannelMuted(muted){mediaPlayerState.muted=muted;const iframe=document.getElementById('channelYoutubeIframe');iframe?.contentWindow?.postMessage(JSON.stringify({event:'command',func:muted?'mute':'unMute',args:[]}), '*');$('#muteChannelBtn').textContent=muted?'فتح صوت القناة':'كتم القناة';}
function closeChannelPlayer(){mediaPlayerState={mode:'closed',channel:null,videoId:'',embedUrl:'',youtubeUrl:'',playerType:'',muted:false};renderChannelPlayer();}
function discussChannel(channelId){if(!me)return openModal();const card=document.querySelector(`.channelCard[data-channel="${CSS.escape(channelId)}"]`),title=card?.querySelector('b')?.textContent||mediaPlayerState.channel?.name||'';pendingRoomSource={sourceChannelId:channelId,sourceYoutubeVideoId:mediaPlayerState.channel?.id===channelId?mediaPlayerState.videoId:''};toast('اكتب عنوان غرفة النقاش ثم احفظها.');$('#newRoomBtn')?.click();if($('#roomNameInput'))$('#roomNameInput').value=`نقاش ${title}`.slice(0,60);if($('#roomDescInput'))$('#roomDescInput').value=`نقاش مرتبط بقناة ${title}`.slice(0,240);}
async function toggleChannelFollow(btn){if(!me)return openModal();const followed=btn.dataset.followed==='1',id=btn.dataset.channel;try{await api(`/api/channels/${encodeURIComponent(id)}/follow`,{method:followed?'DELETE':'POST'});btn.dataset.followed=followed?'0':'1';btn.textContent=followed?'متابعة':'إلغاء المتابعة';}catch(e){toast(e.message);}}
$('#refreshChannelsBtn')?.addEventListener('click',()=>loadChannelHome());
$('#loadMoreChannels')?.addEventListener('click',()=>loadChannels(false));
['#channelRegion','#channelCountry','#channelLanguage'].forEach(sel=>$(sel)?.addEventListener('change',()=>loadChannels(true)));
$('#channelSearch')?.addEventListener('input',()=>{clearTimeout(loadChannels.searchTimer);loadChannels.searchTimer=setTimeout(()=>loadChannels(true),300);});
$('#channelLiveOnly')?.addEventListener('click',()=>{channelState.liveOnly=!channelState.liveOnly;$('#channelLiveOnly').classList.toggle('primary',channelState.liveOnly);loadChannels(true);});
$('#minimizeChannelPlayer')?.addEventListener('click',()=>{mediaPlayerState.mode='mini';renderChannelPlayer();});
$('#expandMiniPlayer')?.addEventListener('click',()=>{mediaPlayerState.mode='expanded';renderChannelPlayer();});
$('#closeChannelPlayer')?.addEventListener('click',closeChannelPlayer);
$('#closeMiniPlayer')?.addEventListener('click',closeChannelPlayer);
$('#muteChannelBtn')?.addEventListener('click',()=>setChannelMuted(!mediaPlayerState.muted));
$('#discussChannelBtn')?.addEventListener('click',()=>mediaPlayerState.channel&&discussChannel(mediaPlayerState.channel.id));
function renderRooms(){ $('#rooms').innerHTML=rooms.map(r=>{const liveLabel=r.live?.topicTitle?`حوار مباشر: ${esc(r.live.topicTitle)}`:'بث مباشر الآن';return `<div class="roomItem ${currentRoom===r.id?'active':''} ${r.live?.active?'hasLive':''}" data-id="${esc(r.id)}"><button class="roomBtn" data-id="${esc(r.id)}"><span>${esc(r.name)}${r.live?.active?'<em class="roomLiveBadge">LIVE</em>':''}</span><small>${r.live?.active?liveLabel:`${r.posts||0}/${r.messages||0}`}</small></button>${canManageRoom(r)?`<div class="roomManage"><button class="editRoom">تعديل</button><button class="deleteRoom danger">حذف</button></div>`:''}</div>`}).join(''); document.querySelectorAll('.roomBtn').forEach(b=>b.onclick=()=>selectRoom(b.dataset.id));document.querySelectorAll('.editRoom').forEach(btn=>btn.onclick=()=>openRoomForm(btn.closest('.roomItem').dataset.id));document.querySelectorAll('.deleteRoom').forEach(btn=>btn.onclick=()=>deleteRoom(btn.closest('.roomItem').dataset.id));renderLiveTicker(); }
function fillRoomSelect(){ $('#postRoom').innerHTML=rooms.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join(''); }
function openRoomForm(id=''){if(!me)return openModal();roomEditId=id;const room=rooms.find(r=>r.id===id);$('#roomNameInput').value=room?.name||'';$('#roomDescInput').value=room?.description||'';$('#roomForm').classList.remove('hidden');$('#roomNameInput').focus();}
async function saveRoom(){const name=$('#roomNameInput').value.trim(),description=$('#roomDescInput').value.trim();if(name.length<3)return toast('اسم الغرفة قصير');try{const url=roomEditId?`/api/rooms/${roomEditId}`:'/api/rooms',body={name,description};if(!roomEditId&&pendingRoomSource)Object.assign(body,pendingRoomSource);await api(url,{method:roomEditId?'PATCH':'POST',body:JSON.stringify(body)});$('#roomForm').classList.add('hidden');roomEditId='';pendingRoomSource=null;await refreshRooms();toast('تم حفظ الغرفة');}catch(e){toast(e.message);}}
async function deleteRoom(id){const room=rooms.find(r=>r.id===id);if(!room)return;if(!confirm(`حذف غرفة "${room.name}" وكل منشوراتها ورسائلها؟`))return;try{await api(`/api/rooms/${id}`,{method:'DELETE'});if(currentRoom===id){currentRoom='';$('#chatBox').innerHTML='';$('#chatSend').classList.add('hidden');}await refreshRooms();await loadFeed();toast('تم حذف الغرفة');}catch(e){toast(e.message);}}
async function selectRoom(id){
  if(liveHost&&currentRoom&&currentRoom!==id)return toast('أنت تبث الآن. أنهِ البث قبل الانتقال إلى ساحة أخرى.');
  if(currentRoom && currentRoom!==id){ await leaveVoice(); await stopWatchingLive(); if(liveBroadcaster) await leaveLiveGuest(); }
  currentRoom=id; const room=rooms.find(r=>r.id===id); if(!room)return;
  currentRoomPower={role:'guest',canModerate:false,canManage:false,banned:false,roomStatus:room.status||'active'};
  if(me){try{currentRoomPower=await api(`/api/rooms/${id}/permissions`);}catch{}}
  $('#roomTitle').textContent=room.name; $('#roomDesc').textContent=room.description; $('#postRoom').value=id; $('#roomContext').textContent=currentRoomPower.role==='owner'?'غرفتك':currentRoomPower.role==='moderator'?'أنت مشرف في هذه الغرفة':'ساحة سياسية'; renderRooms(); socket.emit('room:join',id);
  $('#manageRoomBtn').classList.toggle('hidden',!canModerateCurrentRoom());
  $('#chatNotice').textContent=`دردشة ${room.name}`; $('#chatSend').classList.toggle('hidden',!canAct()||currentRoomPower.banned); resetRealtimeUi();
  $('#globalChannels')?.classList.add('hidden');
  await Promise.all([loadFeed(),loadChat()]);
  $('#newsStrip').classList.add('hidden');
}
async function loadFeed(){ const p=new URLSearchParams(); if(currentRoom)p.set('room',currentRoom); if(currentSearch)p.set('q',currentSearch); const list=await api(`/api/feed${p.toString()?`?${p}`:''}`); currentFeed=list; $('#feed').innerHTML=list.length?list.map(postHtml).join(''):'<div class="empty">لا توجد منشورات مطابقة.</div>'; wirePosts(); }
function initLanguage(){const select=$('#languageSelect');if(!select)return;const names=typeof Intl!=='undefined'&&Intl.DisplayNames?new Intl.DisplayNames([navigator.language||'en'],{type:'language'}):null;select.innerHTML=languages.map(code=>`<option value="${code}">${esc(names?.of(code)||code.toUpperCase())}</option>`).join('');select.value=localStorage.getItem('uiLang')||'ar';select.onchange=()=>{localStorage.setItem('uiLang',select.value);applyLanguage();};applyLanguage();}
function applyLanguage(){const lang=localStorage.getItem('uiLang')||'ar';document.documentElement.lang=lang;document.documentElement.dir=['ar','fa','ur','he'].includes(lang)?'rtl':'ltr';$('#homeBtn').textContent=t('home');$('#loginBtn').textContent=t('login');$('#messagesBtn').textContent=t('messages');$('#notificationsBtn').childNodes[0].nodeValue=t('notifications')+' ';$('#profileBtn').textContent=t('profile');$('#logoutBtn').textContent=t('logout');$('#searchBtn').textContent=t('search');if(!currentRoom)$('#roomTitle').textContent=t('allRooms');renderLiveTicker();}
async function loadPoliticalNews(force=false){const wrap=$('#newsStrip');if(!wrap||currentRoom)return;if(newsLoaded&&!force){wrap.classList.remove('hidden');return;}wrap.classList.remove('hidden');wrap.innerHTML=`<b>${esc(t('news'))}</b><span class="muted">جاري تحميل الأخبار...</span>`;try{const data=await api('/api/political-news');newsLoaded=true;const items=data.items||[],sources=[...new Set(items.map(x=>x.source))],langs=[...new Set(items.map(x=>x.lang).filter(Boolean))];wrap.innerHTML=`<div class="newsHead"><b>${esc(t('news'))}</b><div class="newsFilters"><select id="newsSourceFilter"><option value="">كل المصادر</option>${sources.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="newsLangFilter"><option value="">كل اللغات</option>${langs.map(x=>`<option value="${esc(x)}">${esc(x.toUpperCase())}</option>`).join('')}</select><button class="newsRefresh" id="refreshNewsBtn">تحديث</button></div></div><div class="newsItems" id="newsItems"></div>`;const paint=()=>{const source=$('#newsSourceFilter').value,lang=$('#newsLangFilter').value,filtered=items.filter(n=>(!source||n.source===source)&&(!lang||n.lang===lang));$('#newsItems').innerHTML=filtered.map(n=>`<a class="newsItem" href="${esc(n.link)}" target="_blank" rel="noopener"><span>${esc(n.source)} · ${esc((n.lang||'').toUpperCase())}</span><strong>${esc(n.title)}</strong><small>${esc(n.summary||'')}</small></a>`).join('')||'<div class="empty">لا توجد أخبار ضمن هذا الفلتر.</div>';};paint();$('#newsSourceFilter').onchange=paint;$('#newsLangFilter').onchange=paint;$('#refreshNewsBtn').onclick=()=>{newsLoaded=false;loadPoliticalNews(true);};}catch(e){wrap.innerHTML=`<b>${esc(t('news'))}</b><button class="newsRefresh" id="refreshNewsBtn">إعادة المحاولة</button><span class="muted">${esc(e.message)}</span>`;$('#refreshNewsBtn').onclick=()=>loadPoliticalNews(true);}}
function mediaHtml(media=[]){ return media.map(m=>m.type==='image'?`<a href="${esc(m.url)}" target="_blank"><img class="postImage" src="${esc(m.url)}" alt="صورة مرفقة"></a>`:`<video class="postVideo" src="${esc(m.url)}" controls preload="metadata"></video>`).join(''); }
function postHtml(post){ const room=rooms.find(r=>r.id===post.roomId), roomModeration=currentRoom===post.roomId&&canModerateCurrentRoom(), canDelete=me&&(post.userId===me.id||roomModeration), canEdit=me&&post.userId===me.id; const quick=canAct()?`<div class="quickComment"><input maxlength="1500" placeholder="اكتب تعليقًا..." aria-label="تعليق"><button class="quickCommentSend primary">إرسال</button></div>`:''; return `<article class="post" data-id="${post.id}"><div class="postHead"><button class="authorBtn" data-user="${esc(post.userId)}">${avatarHtml(post.author,'authorAvatar')}<span><b class="author">${esc(post.author?.displayName||post.author?.username||'مستخدم')}</b><small class="handle">@${esc(post.author?.username||'')}</small></span></button><span class="time">${fmt(post.createdAt)}${post.editedAt?' · عُدّل':''}</span></div><div class="roomTag">${esc(room?.name||'')}</div>${post.text?`<div class="postText">${esc(post.text)}</div>`:''}<div class="postMedia">${mediaHtml(post.media)}</div><div class="actions"><button class="likeBtn ${post.likedByMe?'liked':''}">♥ ${post.likes}</button><button class="commentBtn">💬 ${post.comments}</button><button class="shareBtn">مشاركة</button><button class="reportBtn">إبلاغ</button>${canEdit?'<button class="editBtn">تعديل النص</button>':''}${canDelete?'<button class="deleteBtn danger">حذف</button>':''}</div>${quick}<div class="comments hidden"></div></article>`; }
function buttonCount(btn){return Number((btn.textContent.match(/\d+/)||['0'])[0]);}
function setCommentCount(el,count){el.querySelector('.commentBtn').textContent=`💬 ${Math.max(0,count)}`;}
function commentHtml(c,roomId=''){const roomModeration=currentRoom===roomId&&canModerateCurrentRoom();return `<div class="comment" data-id="${esc(c.id)}"><b>${esc(c.author?.displayName||c.author?.username)}</b> ${esc(c.text)}${me&&(c.userId===me.id||roomModeration)?' <button class="deleteComment danger">حذف</button>':''}</div>`;}
function wireCommentDeletes(el,box){box.querySelectorAll('.deleteComment').forEach(btn=>btn.onclick=async()=>{if(!confirm('حذف التعليق؟'))return;const comment=btn.closest('.comment');try{await api(`/api/comments/${comment.dataset.id}`,{method:'DELETE'});comment.remove();setCommentCount(el,buttonCount(el.querySelector('.commentBtn'))-1);}catch(e){toast(e.message);}});}
function wirePosts(){ document.querySelectorAll('.post').forEach(el=>{const id=el.dataset.id; el.querySelector('.authorBtn')?.addEventListener('click',()=>openProfile(el.querySelector('.authorBtn').dataset.user)); el.querySelector('.likeBtn').onclick=async()=>{if(!me)return openModal();const btn=el.querySelector('.likeBtn');if(btn.disabled)return;const oldCount=buttonCount(btn), oldLiked=btn.classList.contains('liked'), nextLiked=!oldLiked, nextCount=oldCount+(nextLiked?1:-1);btn.classList.toggle('liked',nextLiked);btn.textContent=`♥ ${Math.max(0,nextCount)}`;btn.disabled=true;try{const x=await api(`/api/posts/${id}/like`,{method:'POST'});btn.classList.toggle('liked',!!x.liked);btn.textContent=`♥ ${x.count}`;}catch(e){btn.classList.toggle('liked',oldLiked);btn.textContent=`♥ ${oldCount}`;toast(e.message);}finally{btn.disabled=false;}}; el.querySelector('.commentBtn').onclick=()=>toggleComments(el,id); const quickInput=el.querySelector('.quickComment input'),quickSend=el.querySelector('.quickCommentSend'); if(quickInput&&quickSend){const sendQuick=async()=>{const text=quickInput.value.trim();if(!text)return;quickSend.disabled=true;try{await api(`/api/posts/${id}/comments`,{method:'POST',body:JSON.stringify({text})});quickInput.value='';setCommentCount(el,buttonCount(el.querySelector('.commentBtn'))+1);const box=el.querySelector('.comments');if(!box.classList.contains('hidden')){box.classList.add('hidden');await toggleComments(el,id);}toast('تم نشر التعليق');}catch(e){toast(e.message);}finally{quickSend.disabled=false;quickInput.focus();}};quickSend.onclick=sendQuick;quickInput.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendQuick();}};} el.querySelector('.shareBtn').onclick=async()=>{const link=`${location.origin}/?post=${encodeURIComponent(id)}`;try{await navigator.clipboard.writeText(link);toast('تم نسخ رابط المنشور');}catch{prompt('انسخ الرابط:',link);}}; el.querySelector('.reportBtn').onclick=async()=>{if(!me)return openModal();const reason=prompt('سبب البلاغ؟');if(!reason?.trim())return;try{await api('/api/reports',{method:'POST',body:JSON.stringify({targetType:'post',targetId:id,reason})});toast('تم استلام البلاغ');}catch(e){toast(e.message);}}; el.querySelector('.editBtn')?.addEventListener('click',async()=>{const old=el.querySelector('.postText')?.textContent||'';const text=prompt('عدّل النص:',old);if(text===null)return;try{await api(`/api/posts/${id}`,{method:'PATCH',body:JSON.stringify({text})});await loadFeed();}catch(e){toast(e.message);}}); el.querySelector('.deleteBtn')?.addEventListener('click',async()=>{if(!confirm('حذف المنشور والوسائط المرفقة؟'))return;try{await api(`/api/posts/${id}`,{method:'DELETE'});await loadFeed();toast('تم الحذف');}catch(e){toast(e.message);}});}); }
async function toggleComments(el,id){const box=el.querySelector('.comments');if(!box.classList.contains('hidden'))return box.classList.add('hidden');try{const post=currentFeed.find(p=>p.id===id),roomId=post?.roomId||'';const cs=await api(`/api/posts/${id}/comments`);box.innerHTML=cs.map(c=>commentHtml(c,roomId)).join('')+(canAct()?'<div class="commentInput"><input maxlength="1500" placeholder="اكتب تعليقًا"><button class="primary">إرسال</button></div>':'');box.classList.remove('hidden');wireCommentDeletes(el,box);if(canAct()){const input=box.querySelector('.commentInput input'), send=box.querySelector('.commentInput button');const submit=async()=>{const text=input.value.trim();if(!text)return;send.disabled=true;try{const c=await api(`/api/posts/${id}/comments`,{method:'POST',body:JSON.stringify({text})});input.value='';box.querySelector('.commentInput').insertAdjacentHTML('beforebegin',commentHtml(c,roomId));wireCommentDeletes(el,box);setCommentCount(el,buttonCount(el.querySelector('.commentBtn'))+1);}catch(e){toast(e.message);}finally{send.disabled=false;input.focus();}};send.onclick=submit;input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();submit();}};}}catch(e){toast(e.message);}}

$('#postMedia').onchange=()=>{const files=[...$('#postMedia').files];$('#mediaInfo').textContent=files.length?`${files.length} ملف/ملفات مختارة`:'حتى 4 ملفات، 200MB للملف';$('#mediaPreview').innerHTML='';files.slice(0,4).forEach(f=>{const u=URL.createObjectURL(f);$('#mediaPreview').insertAdjacentHTML('beforeend',f.type.startsWith('image/')?`<img src="${u}">`:`<video src="${u}" muted controls></video>`);});};
$('#publishBtn').onclick=async()=>{if(!me)return openModal();if(!canAct())return toast('حسابك لا يملك صلاحية النشر حاليًا');const files=[...$('#postMedia').files];const text=$('#postText').value.trim();if(!text&&!files.length)return toast('اكتب منشورًا أو اختر صورة/فيديو');if(files.length>4)return toast('الحد الأقصى 4 ملفات');const fd=new FormData();fd.append('roomId',$('#postRoom').value);fd.append('text',text);files.forEach(f=>fd.append('media',f));try{$('#publishBtn').disabled=true;$('#publishBtn').textContent='جاري الرفع...';await api('/api/posts',{method:'POST',body:fd});$('#postText').value='';$('#postMedia').value='';$('#mediaPreview').innerHTML='';$('#mediaInfo').textContent='حتى 4 ملفات، 200MB للملف';await loadFeed();toast('تم النشر');}catch(e){toast(e.message);}finally{$('#publishBtn').disabled=false;$('#publishBtn').textContent='نشر';}};

async function loadChat(){if(!currentRoom){$('#chatBox').innerHTML='';return;}try{const ms=await api(`/api/chat/${currentRoom}`);$('#chatBox').innerHTML=ms.map(msgHtml).join('');wireChatDeletes();$('#chatBox').scrollTop=$('#chatBox').scrollHeight;}catch(e){toast(e.message);}}
const msgHtml=m=>{const roomModeration=currentRoom===m.roomId&&canModerateCurrentRoom();return `<div class="msg" data-id="${esc(m.id)}"><b>${esc(m.author?.displayName||m.author?.username||'مستخدم')}</b><div>${esc(m.text)}</div><small class="time">${fmt(m.createdAt)}</small>${me&&(m.userId===me.id||roomModeration)?' <button class="deleteMsg danger">حذف</button>':''}</div>`;}
const liveMsgHtml=m=>`<div class="msg liveMsg" data-id="${esc(m.id)}"><b>${esc(m.author?.displayName||m.author?.username||'مستخدم')}</b><div>${esc(m.text)}</div><small class="time">${fmt(m.createdAt)}</small></div>`;
function setChatTitle(text){const title=document.querySelector('.chatCard .cardTitle b');if(title)title.textContent=text;}
function isLiveChatActive(){return !!currentRoom&&!!activeLive;}
function syncRoomLiveStatus(roomId, live){const room=rooms.find(r=>r.id===roomId);if(room){room.live=live||null;renderRooms();}}
function renderLiveChat(messages=[]){liveMessages=messages||[];setChatTitle('تعليقات البث المباشر');$('#chatNotice').textContent=activeLive?`تعليقات هذا البث فقط`:'تعليقات بثك المباشر';$('#chatBox').innerHTML=liveMessages.length?liveMessages.map(liveMsgHtml).join(''):'<div class="empty">لا توجد تعليقات في هذا البث بعد.</div>';$('#chatBox').scrollTop=$('#chatBox').scrollHeight;}
function wireChatDeletes(){document.querySelectorAll('.deleteMsg').forEach(btn=>btn.onclick=async()=>{if(!confirm('حذف رسالة الدردشة؟'))return;try{await api(`/api/chat-messages/${btn.closest('.msg').dataset.id}`,{method:'DELETE'});btn.closest('.msg').remove();}catch(e){toast(e.message);}});}
socket.on('room:message',m=>{if(m.roomId!==currentRoom||isLiveChatActive())return;$('#chatBox').insertAdjacentHTML('beforeend',msgHtml(m));wireChatDeletes();$('#chatBox').scrollTop=$('#chatBox').scrollHeight;}); socket.on('room:message-deleted',m=>{if(m.roomId===currentRoom&&!isLiveChatActive())document.querySelector(`.msg[data-id="${CSS.escape(m.id)}"]`)?.remove();}); socket.on('room:updated',async()=>{await refreshRooms();}); socket.on('room:deleted',async m=>{if(m.roomId===currentRoom)$('#homeBtn').click();await refreshRooms();}); socket.on('room:error',d=>toast(d?.error||'تعذر إرسال الرسالة')); socket.on('feed:new',e=>{if(!currentRoom||currentRoom===e.roomId)loadFeed();}); socket.on('feed:changed',e=>{if(!currentRoom||currentRoom===e.roomId)loadFeed();});
socket.on('rooms:live-status',d=>syncRoomLiveStatus(d.roomId,d.active?d.live:null));
function sendChat(){const text=$('#chatInput').value.trim();if(!me)return openModal();if(!canAct())return toast('حسابك لا يملك صلاحية إرسال الدردشة حاليًا');if(!currentRoom)return toast('اختر ساحة أولًا');if(!text)return;socket.emit(isLiveChatActive()?'live:message':'room:message',{token,roomId:currentRoom,text});$('#chatInput').value='';} $('#chatBtn').onclick=sendChat; $('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChat();}};

function makePc(kind, peerId, stream, onTrack){const pc=new RTCPeerConnection(RTC_CONFIG);if(stream)stream.getTracks().forEach(t=>pc.addTrack(t,stream));pc.onicecandidate=e=>{if(e.candidate)socket.emit('rtc:ice',{to:peerId,candidate:e.candidate,kind,roomId:currentRoom});};pc.ontrack=onTrack;return pc;}
async function ensureVoiceStream(){if(voiceStream)return voiceStream;voiceStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});return voiceStream;}
async function createVoiceOffer(peerId){const s=await ensureVoiceStream();const pc=makePc('voice',peerId,s,e=>attachRemoteAudio(peerId,e.streams[0]));voicePeers.set(peerId,pc);await pc.setLocalDescription(await pc.createOffer());socket.emit('rtc:offer',{to:peerId,sdp:pc.localDescription,kind:'voice',roomId:currentRoom});}
function attachRemoteAudio(id,stream){let a=document.getElementById(`audio-${id}`);if(!a){a=document.createElement('audio');a.id=`audio-${id}`;a.autoplay=true;$('#remoteAudios').appendChild(a);}a.srcObject=stream;}
async function joinVoice(){if(!me)return openModal();if(!canAct())return toast('حسابك لا يملك صلاحية الدخول الصوتي حاليًا');if(!currentRoom)return toast('اختر ساحة أولًا');try{await ensureVoiceStream();socket.emit('voice:join',{token,roomId:currentRoom});$('#joinVoiceBtn').classList.add('hidden');$('#muteBtn').classList.remove('hidden');$('#leaveVoiceBtn').classList.remove('hidden');$('#voiceStatus').textContent='متصل بالغرفة الصوتية';}catch(e){toast('تعذر تشغيل الميكروفون: '+e.message);}}
async function leaveVoice(){if(currentRoom)socket.emit('voice:leave',{roomId:currentRoom});for(const pc of voicePeers.values())pc.close();voicePeers.clear();if(voiceStream){voiceStream.getTracks().forEach(t=>t.stop());voiceStream=null;}$('#remoteAudios').innerHTML='';$('#joinVoiceBtn').classList.remove('hidden');$('#muteBtn').classList.add('hidden');$('#leaveVoiceBtn').classList.add('hidden');$('#voiceStatus').textContent='غير متصل';voiceMuted=false;$('#muteBtn').textContent='كتم الميكروفون';}
$('#joinVoiceBtn').onclick=joinVoice; $('#leaveVoiceBtn').onclick=leaveVoice; $('#muteBtn').onclick=()=>{if(!voiceStream)return;voiceMuted=!voiceMuted;voiceStream.getAudioTracks().forEach(t=>t.enabled=!voiceMuted);$('#muteBtn').textContent=voiceMuted?'فتح الميكروفون':'كتم الميكروفون';};
socket.on('voice:peers',async d=>{if(d.roomId!==currentRoom)return;for(const id of d.peers)await createVoiceOffer(id);}); socket.on('voice:user-left',d=>{voicePeers.get(d.socketId)?.close();voicePeers.delete(d.socketId);document.getElementById(`audio-${d.socketId}`)?.remove();}); socket.on('voice:count',d=>{if(d.roomId===currentRoom)$('#voiceCount').textContent=d.count;}); socket.on('voice:error',d=>toast(d.error));

async function startLive(){if(!me)return openModal();if(!canAct())return toast('حسابك لا يملك صلاحية بدء البث حاليًا');if(!currentRoom)return toast('اختر ساحة أولًا');if(activeLive)return toast('يوجد بث مباشر قائم في هذه الساحة الآن');try{liveStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});liveMuted=false;liveHost=true;liveBroadcaster=true;liveMessages=[];renderLiveChat([]);showLocalLive();$('#liveStatus').textContent='أنت تبث الآن';updateLiveActionButtons();socket.emit('live:start',{token,roomId:currentRoom,title:$('#liveTopicTitleInput').value.trim()});}catch(e){toast('تعذر تشغيل الكاميرا/الميكروفون: '+e.message);}}
function updateLiveStageLayout(){const stage=$('#liveStage');const count=stage.querySelectorAll('.liveTile:not(.hidden)').length;stage.classList.remove('slots-1','slots-2','slots-4','slots-6');stage.classList.add(count<=1?'slots-1':count<=2?'slots-2':count<=4?'slots-4':'slots-6');document.body.classList.toggle('liveMode',!!currentRoom&&(liveBroadcaster||liveWatching));}
function liveBroadcasterName(id){const b=(activeLive?.broadcasters||[]).find(x=>x.socketId===id);return b?.displayName||(id===socket.id?(me?.displayName||me?.username):'مشارك في البث');}
function updateLiveTileLabels(){const local=$('#liveLocalName');if(local)local.textContent=liveBroadcasterName(socket.id)||'أنا';document.querySelectorAll('.remoteLive').forEach(v=>{const label=document.querySelector(`#live-remote-tile-${CSS.escape(v.dataset.socket||'')} .liveTileName`);if(label)label.textContent=liveBroadcasterName(v.dataset.socket);});}
function showLocalLive(){if(!liveStream)return;const v=$('#liveVideo'),tile=$('#liveLocalTile');v.srcObject=liveStream;v.muted=true;v.className='liveVideo';tile?.classList.remove('hidden');updateLiveTileLabels();renderActiveSpeaker(false);updateLiveStageLayout();}
function removeLiveVideo(id){document.getElementById(`live-remote-tile-${id}`)?.remove();updateLiveStageLayout();}
function attachRemoteLive(id,stream){let v=document.getElementById(`live-remote-${id}`);if(!v){const tile=document.createElement('div');tile.id=`live-remote-tile-${id}`;tile.className='liveTileBox liveTile';tile.innerHTML=`<span class="liveTileName">${esc(liveBroadcasterName(id))}</span><video id="live-remote-${esc(id)}" class="remoteLive" autoplay playsinline></video>`;$('#liveStage').appendChild(tile);v=document.getElementById(`live-remote-${id}`);v.dataset.socket=id;}v.srcObject=stream;updateLiveTileLabels();renderActiveSpeaker(false);updateLiveStageLayout();}
function renderActiveSpeaker(renderList=true){document.querySelectorAll('.liveTile').forEach(el=>el.classList.remove('activeSpeakerTile'));const id=activeLive?.activeSpeakerSocketId||'';if(id===socket.id)$('#liveLocalTile')?.classList.add('activeSpeakerTile');else document.getElementById(`live-remote-tile-${id}`)?.classList.add('activeSpeakerTile');if(renderList)renderLiveParticipants();}
function applyTopicPlayback(){const media=$('#liveTopicPanel video');if(!media)return;media.loop=true;media.muted=liveTopicPlayback.muted===true;media.volume=1;if(liveTopicPlayback.playing!==false)media.play().catch(()=>{media.muted=true;media.play().catch(()=>{});});else media.pause();}
function syncLiveTopicCaption(){const panel=$('#liveTopicPanel');if(panel)panel.querySelector('.liveTopicCaption')?.remove();}
function renderLiveTopic(media){const panel=$('#liveTopicPanel');if(!panel)return;if(!media?.url){panel.innerHTML='';panel.dataset.url='';panel.classList.add('hidden');updateLiveStageLayout();return;}const same=panel.dataset.url===media.url;panel.classList.remove('hidden');if(!same){const safeName=esc(media.name||activeLive?.topicTitle||'موضوع الحوار');panel.dataset.url=media.url;panel.innerHTML=media.type==='image'?`<img src="${esc(media.url)}" alt="${safeName}">`:`<video src="${esc(media.url)}" autoplay loop playsinline preload="auto" title="${safeName}"></video>`;const video=panel.querySelector('video');if(video)video.onpause=()=>{if(liveTopicPlayback.playing!==false)setTimeout(()=>video.play().catch(()=>{}),80);};}syncLiveTopicCaption();applyTopicPlayback();updateLiveStageLayout();}
function renderLiveTitle(){const title=activeLive?.topicTitle||'';$('#liveTopicTitleView').textContent='';$('#liveTopicTitleView').classList.add('hidden');if(liveHost&&$('#liveTopicTitleInput').value!==title)$('#liveTopicTitleInput').value=title;syncLiveTopicCaption();}
function updateLiveTitle(){if(!liveHost||!currentRoom)return;const title=$('#liveTopicTitleInput').value.trim();if(activeLive)activeLive.topicTitle=title;renderLiveTitle();socket.emit('live:title',{token,roomId:currentRoom,title});}
function updateTopicControlButtons(){const has=!!activeLive?.topicMedia&&liveHost;const play=$('#liveTopicPlayBtn'),mute=$('#liveTopicMuteBtn');play.classList.toggle('hidden',!has);mute.classList.toggle('hidden',!has);play.textContent=liveTopicPlayback.playing===false?'تشغيل الفيديو':'إيقاف الفيديو';play.title=liveTopicPlayback.playing===false?'تشغيل فيديو موضوع الحوار':'إيقاف فيديو موضوع الحوار';mute.textContent=liveTopicPlayback.muted===true?'🔇':'🔊';mute.title=liveTopicPlayback.muted===true?'فتح صوت الملف':'كتم صوت الملف';mute.setAttribute('aria-label',mute.title);mute.classList.add('liveSoundBtn');mute.classList.toggle('muted',liveTopicPlayback.muted===true);}
function sendTopicControl(next={}){if(!liveHost||!currentRoom)return;liveTopicPlayback={...liveTopicPlayback,...next};applyTopicPlayback();updateTopicControlButtons();socket.emit('live:topic-control',{token,roomId:currentRoom,...liveTopicPlayback});}
function updateLiveTopicFileLabel(){const file=$('#liveTopicMedia')?.files?.[0];$('#liveTopicPickText').textContent=file?`تم اختيار: ${file.name.slice(0,32)}`:'تحميل مقطع الحوار';}
async function uploadLiveTopic(){if(!liveHost||!currentRoom)return;const input=$('#liveTopicMedia');const file=input.files?.[0];if(!file)return toast('اختر مقطع الحوار أولًا');const title=$('#liveTopicTitleInput').value.trim();if(activeLive)activeLive.topicTitle=title;const form=new FormData();form.append('media',file);form.append('title',title);try{$('#liveTopicPick').classList.add('isUploading');$('#liveTopicUploadBtn').disabled=true;if(title)socket.emit('live:title',{token,roomId:currentRoom,title});await api(`/api/live/${currentRoom}/topic-media`,{method:'POST',body:form});liveTopicPlayback={playing:true,muted:false};toast('تم إرسال مقطع الحوار');}catch(e){toast(e.message);}finally{$('#liveTopicPick').classList.remove('isUploading');$('#liveTopicUploadBtn').disabled=false;input.value='';updateLiveTopicFileLabel();}}
async function clearLiveTopic(){if(!liveHost||!currentRoom)return;try{await api(`/api/live/${currentRoom}/topic-media`,{method:'DELETE'});toast('تمت إزالة موضوع الحوار');}catch(e){toast(e.message);}}
function applyTopicPlayback(){const panel=$('#liveTopicPanel'),media=panel?.querySelector('video'),iframe=panel?.querySelector('iframe');if(iframe){const cmd=liveTopicPlayback.playing===false?'pauseVideo':'playVideo';iframe.contentWindow?.postMessage(JSON.stringify({event:'command',func:cmd,args:[]}), '*');iframe.contentWindow?.postMessage(JSON.stringify({event:'command',func:liveTopicPlayback.muted===true?'mute':'unMute',args:[]}), '*');return;}if(!media)return;media.loop=true;media.muted=liveTopicPlayback.muted===true;media.volume=1;if(liveTopicPlayback.playing!==false)media.play().catch(()=>{media.muted=true;media.play().catch(()=>{});});else media.pause();}
function renderLiveTopic(media){const panel=$('#liveTopicPanel');if(!panel)return;if(!media?.url){panel.innerHTML='';panel.dataset.url='';panel.classList.add('hidden');updateLiveStageLayout();return;}const src=media.type==='channel'?normalizedEmbedUrl(media.url):media.url,same=panel.dataset.url===src;panel.classList.remove('hidden');if(!same){const safeName=esc(media.name||activeLive?.topicTitle||'موضوع الحوار');panel.dataset.url=src;if(media.type==='channel')panel.innerHTML=`<iframe src="${esc(src)}" title="${safeName}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;else panel.innerHTML=media.type==='image'?`<img src="${esc(src)}" alt="${safeName}">`:`<video src="${esc(src)}" autoplay loop playsinline preload="auto" title="${safeName}"></video>`;const video=panel.querySelector('video');if(video)video.onpause=()=>{if(liveTopicPlayback.playing!==false)setTimeout(()=>video.play().catch(()=>{}),80);};}syncLiveTopicCaption();applyTopicPlayback();updateLiveStageLayout();}
async function loadLiveTopicChannels(){const select=$('#liveTopicChannelSelect');if(!select||liveTopicChannelsLoaded)return;try{const data=await api('/api/channels/live?limit=30');const channels=data.channels||[];select.innerHTML='<option value="">قناة الحوار</option>'+channels.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');liveTopicChannelsLoaded=true;}catch(e){select.innerHTML='<option value="">تعذر تحميل القنوات</option>';}}
async function sendLiveTopicChannel(){if(!liveHost||!currentRoom)return;const select=$('#liveTopicChannelSelect'),channelId=select?.value||'';if(!channelId)return toast('اختر قناة الحوار أولًا');const title=$('#liveTopicTitleInput').value.trim();if(activeLive)activeLive.topicTitle=title;try{$('#liveTopicChannelBtn').disabled=true;if(title)socket.emit('live:title',{token,roomId:currentRoom,title});await api(`/api/live/${currentRoom}/topic-channel`,{method:'POST',body:JSON.stringify({channelId,title}),headers:{'Content-Type':'application/json'}});liveTopicPlayback={playing:true,muted:false};toast('تم إرسال قناة الحوار');}catch(e){toast(e.message);}finally{$('#liveTopicChannelBtn').disabled=false;}}
function clearRemoteLive(){document.querySelectorAll('.liveTileBox[id^="live-remote-tile-"]').forEach(v=>v.remove());for(const pc of liveViewerPeers.values())pc.close();liveViewerPeers.clear();updateLiveStageLayout();}
async function stopLive(){if(!liveHost)return;if(currentRoom)socket.emit('live:stop',{roomId:currentRoom});for(const pc of livePeers.values())pc.close();livePeers.clear();if(liveStream){liveStream.getTracks().forEach(t=>t.stop());liveStream=null;}liveMessages=[];liveLiked=false;liveWatching=false;liveMuted=false;liveHost=false;liveBroadcaster=false;activeLive=null;clearRemoteLive();renderLiveTitle();renderLiveTopic(null);$('#liveVideo').srcObject=null;$('#liveLocalTile')?.classList.add('hidden');updateLiveActionButtons();renderLiveParticipants();if(currentRoom)loadChat();}
async function leaveLiveGuest(notify=true){if(!liveBroadcaster||liveHost)return;if(notify&&currentRoom)socket.emit('live:guest-leave',{token,roomId:currentRoom});for(const pc of livePeers.values())pc.close();livePeers.clear();if(liveStream){liveStream.getTracks().forEach(t=>t.stop());liveStream=null;}liveMuted=false;liveBroadcaster=false;clearRemoteLive();renderLiveTopic(activeLive?.topicMedia||null);$('#liveVideo').srcObject=null;$('#liveLocalTile')?.classList.add('hidden');$('#liveStatus').textContent=activeLive?'مشاهدة البث المباشر':'لا يوجد بث مباشر الآن';updateLiveActionButtons();}
async function cleanupForcedLive(){for(const pc of livePeers.values())pc.close();livePeers.clear();for(const pc of liveViewerPeers.values())pc.close();liveViewerPeers.clear();if(liveStream){liveStream.getTracks().forEach(t=>t.stop());liveStream=null;}liveMessages=[];liveLiked=false;liveWatching=false;liveMuted=false;liveHost=false;liveBroadcaster=false;activeLive=null;$('#liveVideo').srcObject=null;$('#liveLocalTile')?.classList.add('hidden');clearRemoteLive();renderLiveTitle();renderLiveTopic(null);updateLiveActionButtons();renderLiveParticipants();if(currentRoom)loadChat();}
async function watchLive(){if(!currentRoom)return;liveWatching=true;renderLiveChat(activeLive?.messages||[]);updateLiveStageLayout();socket.emit('live:watch',{token,roomId:currentRoom});$('#watchLiveBtn').classList.add('hidden');$('#liveStatus').textContent='جاري الاتصال بالبث...';}
async function stopWatchingLive(){if(currentRoom&&!liveBroadcaster)socket.emit('live:unwatch',{roomId:currentRoom});liveWatching=false;for(const pc of liveViewerPeers.values())pc.close();liveViewerPeers.clear();if(!liveBroadcaster){liveMessages=[];clearRemoteLive();renderLiveTopic(null);if(currentRoom)loadChat();}}
function requestLiveStatus(){if(currentRoom)socket.emit('live:status-request',{roomId:currentRoom});}
function updateLiveActionButtons(){
  const canStartLive=canAct()&&!!currentRoom&&!currentRoomPower.banned&&!activeLive&&!liveBroadcaster;
  const broadcasting=liveHost||liveBroadcaster;
  $('#startLiveBtn').classList.toggle('hidden',broadcasting||liveWatching);
  $('#startLiveBtn').disabled=!canStartLive;
  $('#startLiveBtn').textContent=activeLive&&!broadcasting?'بدء بث مباشر':'ابدأ بث فيديو';
  $('#startLiveBtn').title=activeLive&&!broadcasting?'يوجد بث مباشر قائم في هذه الساحة الآن':'';
  $('#watchLiveBtn').classList.toggle('hidden',!activeLive||broadcasting);
  $('#liveLikeBtn').classList.toggle('hidden',!activeLive&&!broadcasting);
  $('#liveLikeBtn').textContent=`إعجاب ${activeLive?.likeCount||0}`;
  $('#liveLikeBtn').classList.toggle('liked',liveLiked);
  $('#liveMuteBtn').classList.toggle('hidden',!broadcasting);
  $('#liveMuteBtn').textContent=liveMuted?'🔇':'🔊';
  $('#liveMuteBtn').title=liveMuted?'فتح الصوت':'كتم الصوت';
  $('#liveMuteBtn').classList.toggle('muted',liveMuted);
  $('#liveMuteBtn').classList.add('liveSoundBtn');
  $('#liveShareBtn').classList.toggle('hidden',!currentRoom);
  $('#stopLiveBtn').classList.toggle('hidden',!liveHost);
  $('#leaveGuestBtn').classList.toggle('hidden',!liveBroadcaster||liveHost);
  $('#inviteGuestBtn').classList.toggle('hidden',!liveHost);
  $('#liveGuestSelect').classList.toggle('hidden',!liveHost);
  $('#liveTopicTools').classList.toggle('hidden',!liveHost);
  $('#liveTopicTitleInput').classList.toggle('hidden',!(liveHost||canStartLive));
  $('#liveTopicPick').classList.toggle('hidden',!liveHost);
  $('#liveTopicUploadBtn').classList.toggle('hidden',!liveHost);
  $('#liveTopicChannelSelect')?.classList.toggle('hidden',!liveHost);
  $('#liveTopicChannelBtn')?.classList.toggle('hidden',!liveHost);
  $('#clearLiveTopicBtn').classList.toggle('hidden',!liveHost||!activeLive?.topicMedia);
  $('#requestGuestBtn').classList.toggle('hidden',!activeLive||liveBroadcaster||liveHost||!liveWatching||!canAct());
  updateTopicControlButtons();
  if(liveHost){loadLiveGuestOptions();loadLiveTopicChannels();}
  if(!activeLive&&!liveBroadcaster){
    if(!currentRoom)$('#liveStatus').textContent='اختر ساحة أولًا لبدء بث مباشر';
    else if(!me)$('#liveStatus').textContent='سجل الدخول لبدء بث مباشر';
    else if(!canAct())$('#liveStatus').textContent='حسابك لا يملك صلاحية بدء البث حاليًا';
    else if(currentRoomPower.banned)$('#liveStatus').textContent='لا يمكنك بدء بث في هذه الساحة';
    else $('#liveStatus').textContent='لا يوجد بث مباشر الآن';
  }
}
function toggleLiveMute(){if(!liveStream)return;liveMuted=!liveMuted;liveStream.getAudioTracks().forEach(t=>t.enabled=!liveMuted);updateLiveActionButtons();}
function toggleLiveLike(){if(!currentRoom||( !activeLive&&!liveBroadcaster))return;socket.emit('live:like',{token,roomId:currentRoom});}
async function shareLive(){if(!currentRoom)return toast('اختر ساحة أولًا');const link=`${location.origin}/?room=${encodeURIComponent(currentRoom)}`;try{await navigator.clipboard.writeText(link);toast('تم نسخ رابط البث');}catch{prompt('انسخ رابط البث:',link);}}
function renderLiveGuestOptions(){
  const select=$('#liveGuestSelect');
  const liveUserIds=new Set((activeLive?.broadcasters||[]).map(b=>b.userId));
  const options=liveInviteCandidates.filter(u=>u.id!==me?.id&&!liveUserIds.has(u.id));
  select.innerHTML=options.length?options.map(u=>`<option value="${esc(u.id)}" data-user="${esc(u.id)}" data-socket="${esc(u.socketId||'')}">${esc(u.displayName||u.username)} @${esc(u.username)}</option>`).join(''):'<option value="">لا يوجد مستخدمون في هذه الساحة</option>';
  $('#inviteGuestBtn').disabled=!options.length;
}
function loadLiveGuestOptions(){
  if(!liveHost||!currentRoom)return;
  socket.emit('live:invite-candidates',{token,roomId:currentRoom});
}
function renderLiveParticipants(){
  const list=activeLive?.broadcasters||[], viewerCount=activeLive?.viewerCount||0, activeSpeaker=activeLive?.activeSpeakerSocketId||'';
  const liveUserIds=new Set(list.map(b=>b.userId));
  const replaceOptions=liveViewers.filter(v=>v.user?.id&&!liveUserIds.has(v.user.id));
  const replaceSelect=targetSocket=>replaceOptions.length?`<select class="liveReplaceSelect" data-target="${esc(targetSocket)}">${replaceOptions.map(v=>`<option value="${esc(v.socketId)}" data-user="${esc(v.user.id)}">${esc(v.user.displayName||v.user.username)} @${esc(v.user.username||'')}</option>`).join('')}</select>`:`<select class="liveReplaceSelect" data-target="${esc(targetSocket)}" disabled><option value="">لا يوجد مشاهدون</option></select>`;
  $('#liveViewerCount').textContent=`${viewerCount} مشاهد`;
  const speakers=list.length?list.map(b=>{const user={displayName:b.displayName,username:b.displayName,avatarUrl:b.avatarUrl||''};const isSpeaking=activeSpeaker===b.socketId;return `<div class="participant speakerRow role-${esc(b.role)} ${isSpeaking?'isSpeaking':''}">${avatarHtml(user)}<div class="meta"><b>${esc(b.displayName||'مشارك في البث')}</b><small>${isSpeaking?'له الكلام الآن':b.role==='host'?'صاحب البث':'ضيف مشارك في البث'}</small></div><span class="liveRoleBadge">${b.role==='host'?'مضيف':'مشارك'}</span>${liveHost?`<div class="miniActions liveManage"><button class="setLiveSpeaker" data-socket="${esc(b.socketId)}">${isSpeaking?'إلغاء الكلام':'إعطاء الكلام'}</button>${b.role==='guest'?`${replaceSelect(b.socketId)}<button class="replaceLiveGuest" data-socket="${esc(b.socketId)}">استبدال</button><button class="muteLiveGuest" data-socket="${esc(b.socketId)}">كتم الضيف</button><button class="removeLiveGuest danger" data-socket="${esc(b.socketId)}">حذف الضيف</button>`:''}</div>`:''}</div>`}).join(''):'<div class="empty">لا يوجد مشاركون في البث بعد.</div>';
  const requests=liveHost?`<div class="liveRequests"><b class="liveSectionTitle"><span>طلبات المشاركة</span><span class="viewerTotal">${liveGuestRequests.length}</span></b>${liveGuestRequests.length?liveGuestRequests.map(r=>`<div class="participant requestRow">${avatarHtml(r.user)}<div class="meta"><b>${esc(r.user?.displayName||r.user?.username||'مستخدم')}</b><small>${r.user?.username?'@'+esc(r.user.username):'طلب مشاركة'}</small></div><div class="miniActions liveManage"><button class="approveGuestRequest" data-socket="${esc(r.socketId)}">قبول</button><button class="declineGuestRequest danger" data-socket="${esc(r.socketId)}">رفض</button></div></div>`).join(''):'<div class="empty">لا توجد طلبات مشاركة.</div>'}</div>`:'';
  const viewers=(liveHost||liveBroadcaster||liveWatching)?`<div class="liveViewers"><b class="liveSectionTitle"><span>المشاهدون</span><span class="viewerTotal">${viewerCount} مشاهد</span></b>${liveViewers.length?liveViewers.map(v=>{const name=v.user?.displayName||v.user?.username||'مشاهد غير مسجل';return `<div class="participant viewerRow">${avatarHtml(v.user||{displayName:name})}<div class="meta"><b>${esc(name)}</b><small>${v.user?.username?'@'+esc(v.user.username):'زائر'}</small></div>${liveHost?`<div class="miniActions liveManage"><button class="inviteViewerGuest" data-user="${esc(v.user?.id||'')}" data-socket="${esc(v.socketId)}" ${v.user?.id?'':'disabled'}>دعوة</button><button class="removeLiveViewer" data-socket="${esc(v.socketId)}">إخراج</button>${v.user?.id?`<button class="banLiveViewer danger" data-socket="${esc(v.socketId)}">حظر</button>`:''}</div>`:''}</div>`}).join(''):'<div class="empty">لا يوجد مشاهدون حالياً.</div>'}</div>`:'';
  $('#liveParticipants').innerHTML=`<div class="liveSpeakers"><b>المضيف والضيوف</b>${speakers}</div>${requests}${viewers}`;
  document.querySelectorAll('.setLiveSpeaker').forEach(btn=>btn.onclick=()=>socket.emit('live:speaker',{token,roomId:currentRoom,socketId:activeSpeaker===btn.dataset.socket?'':btn.dataset.socket}));
  document.querySelectorAll('.approveGuestRequest').forEach(btn=>btn.onclick=()=>socket.emit('live:guest-request-approve',{token,roomId:currentRoom,socketId:btn.dataset.socket}));
  document.querySelectorAll('.declineGuestRequest').forEach(btn=>btn.onclick=()=>socket.emit('live:guest-request-decline',{token,roomId:currentRoom,socketId:btn.dataset.socket}));
  document.querySelectorAll('.inviteViewerGuest').forEach(btn=>btn.onclick=()=>btn.dataset.user&&socket.emit('live:invite',{token,roomId:currentRoom,targetUserId:btn.dataset.user,targetSocketId:btn.dataset.socket}));
  document.querySelectorAll('.removeLiveGuest').forEach(btn=>btn.onclick=()=>socket.emit('live:guest-remove',{token,roomId:currentRoom,targetSocketId:btn.dataset.socket}));
  document.querySelectorAll('.muteLiveGuest').forEach(btn=>btn.onclick=()=>socket.emit('live:broadcaster-mute',{token,roomId:currentRoom,targetSocketId:btn.dataset.socket}));
  document.querySelectorAll('.replaceLiveGuest').forEach(btn=>btn.onclick=()=>replaceLiveGuest(btn.dataset.socket));
  document.querySelectorAll('.removeLiveViewer').forEach(btn=>btn.onclick=()=>socket.emit('live:viewer-remove',{token,roomId:currentRoom,targetSocketId:btn.dataset.socket}));
  document.querySelectorAll('.banLiveViewer').forEach(btn=>btn.onclick=()=>{if(confirm('حظر هذا المشاهد من الساحة؟'))socket.emit('live:viewer-ban',{token,roomId:currentRoom,targetSocketId:btn.dataset.socket});});
  updateLiveTileLabels();
  updateLiveStageLayout();
}
function inviteLiveGuest(){if(!liveHost)return;const select=$('#liveGuestSelect'),option=select.selectedOptions?.[0],targetUserId=option?.dataset.user||select.value,targetSocketId=option?.dataset.socket||'';if(!targetUserId)return toast('اختر مستخدمًا من القائمة');socket.emit('live:invite',{token,roomId:currentRoom,targetUserId,targetSocketId});}
function replaceLiveGuest(targetSocketId){if(!liveHost)return;const select=document.querySelector(`.liveReplaceSelect[data-target="${CSS.escape(targetSocketId)}"]`);const option=select?.selectedOptions?.[0],nextSocketId=select?.value||'',targetUserId=option?.dataset.user||'';if(!targetUserId&&!nextSocketId)return toast('اختر مشاهدًا من قائمة الاستبدال');socket.emit('live:guest-remove',{token,roomId:currentRoom,targetSocketId});socket.emit('live:invite',{token,roomId:currentRoom,targetUserId,targetSocketId:nextSocketId});}
$('#startLiveBtn').onclick=startLive; $('#watchLiveBtn').onclick=watchLive; $('#stopLiveBtn').onclick=stopLive; $('#inviteGuestBtn').onclick=inviteLiveGuest; $('#leaveGuestBtn').onclick=leaveLiveGuest; $('#liveMuteBtn').onclick=toggleLiveMute; $('#liveLikeBtn').onclick=toggleLiveLike; $('#liveShareBtn').onclick=shareLive; $('#requestGuestBtn').onclick=()=>socket.emit('live:guest-request',{token,roomId:currentRoom}); $('#liveTopicMedia').onchange=updateLiveTopicFileLabel; $('#liveTopicUploadBtn').onclick=uploadLiveTopic; $('#liveTopicChannelBtn').onclick=sendLiveTopicChannel; $('#clearLiveTopicBtn').onclick=clearLiveTopic; $('#liveTopicPlayBtn').onclick=()=>sendTopicControl({playing:liveTopicPlayback.playing===false}); $('#liveTopicMuteBtn').onclick=()=>sendTopicControl({muted:liveTopicPlayback.muted===false}); $('#liveTopicTitleInput').onchange=updateLiveTitle; $('#liveTopicTitleInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#liveTopicTitleInput').blur();}};
socket.on('live:invite-candidates',d=>{if(d.roomId!==currentRoom)return;liveInviteCandidates=d.users||[];renderLiveGuestOptions();});
socket.on('live:viewers',d=>{if(d.roomId!==currentRoom)return;liveViewers=d.viewers||[];renderLiveParticipants();});
socket.on('live:likes',d=>{if(d.roomId!==currentRoom)return;if(activeLive)activeLive.likeCount=d.likeCount||0;updateLiveActionButtons();});
socket.on('live:like-result',d=>{if(d.roomId!==currentRoom)return;liveLiked=!!d.liked;if(activeLive)activeLive.likeCount=d.likeCount||0;updateLiveActionButtons();});
socket.on('live:topic-media',d=>{if(d.roomId!==currentRoom)return;if(activeLive)activeLive.topicMedia=d.media||null;renderLiveTopic(d.media||null);updateLiveActionButtons();});
socket.on('live:topic-control',d=>{if(d.roomId!==currentRoom)return;liveTopicPlayback=d.playback||{playing:true,muted:false};applyTopicPlayback();updateTopicControlButtons();});
socket.on('live:title',d=>{if(d.roomId!==currentRoom)return;if(activeLive)activeLive.topicTitle=d.title||'';syncRoomLiveStatus(d.roomId,activeLive);renderLiveTitle();});
socket.on('live:guest-request-result',d=>{if(d.roomId===currentRoom)toast(d.ok?'تم إرسال طلب المشاركة':'تم رفض طلب المشاركة');});
socket.on('live:guest-requests',d=>{if(d.roomId!==currentRoom)return;liveGuestRequests=d.requests||[];renderLiveParticipants();});
socket.on('live:speaker',d=>{if(d.roomId!==currentRoom)return;if(activeLive)activeLive.activeSpeakerSocketId=d.socketId||'';renderActiveSpeaker();});
socket.on('live:message',m=>{if(m.roomId!==currentRoom||!isLiveChatActive())return;const box=$('#chatBox');const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<90;if(!liveMessages.some(x=>x.id===m.id))liveMessages.push(m);if(box.querySelector('.empty'))box.innerHTML='';box.insertAdjacentHTML('beforeend',liveMsgHtml(m));if(nearBottom||document.body.classList.contains('liveMode'))box.scrollTop=box.scrollHeight;});
socket.on('live:invite-candidates-changed',d=>{if(d.roomId===currentRoom&&liveHost)loadLiveGuestOptions();});
socket.on('live:invite-result',d=>toast(d.ok?'تم إرسال دعوة الظهور في البث':'المستخدم غير متصل بهذه الساحة الآن'));
socket.on('live:invite',async d=>{if(d.roomId!==currentRoom||!me)return;if(!confirm(`${d.from?.displayName||'صاحب البث'} يدعوك للظهور معه في البث. هل تقبل؟`))return;try{liveStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});liveBroadcaster=true;liveHost=false;showLocalLive();$('#leaveGuestBtn').classList.remove('hidden');$('#watchLiveBtn').classList.add('hidden');$('#liveStatus').textContent='أنت ضيف في البث المباشر';socket.emit('live:guest-accept',{token,roomId:currentRoom});}catch(e){toast('تعذر تشغيل الكاميرا/الميكروفون: '+e.message);}});
socket.on('live:guest-removed',async d=>{if(d.roomId!==currentRoom)return;await leaveLiveGuest(false);liveWatching=true;socket.emit('live:watch',{token,roomId:currentRoom});toast(d.reason||'تم إنهاء مشاركتك في البث');requestLiveStatus();});
socket.on('live:force-mute',d=>{if(d.roomId!==currentRoom||!liveStream)return;liveMuted=true;liveStream.getAudioTracks().forEach(t=>t.enabled=false);updateLiveActionButtons();toast(d.reason||'تم كتم صوتك في البث');});
socket.on('live:viewer-removed',async d=>{if(d.roomId!==currentRoom)return;await stopWatchingLive();$('#liveStatus').textContent='تم إيقاف مشاهدتك للبث';toast(d.reason||'تم إخراجك من البث');requestLiveStatus();});
socket.on('live:broadcaster-added',d=>{if(d.roomId!==currentRoom)return;if(activeLive){activeLive.broadcasters=activeLive.broadcasters||[];if(!activeLive.broadcasters.some(x=>x.socketId===d.broadcaster.socketId))activeLive.broadcasters.push(d.broadcaster);}renderLiveParticipants();});
socket.on('live:broadcaster-removed',d=>{if(d.roomId!==currentRoom)return;activeLive&&(activeLive.broadcasters=(activeLive.broadcasters||[]).filter(x=>x.socketId!==d.socketId));livePeers.get(d.socketId)?.close();livePeers.delete(d.socketId);liveViewerPeers.get(d.socketId)?.close();liveViewerPeers.delete(d.socketId);removeLiveVideo(d.socketId);renderLiveParticipants();});
socket.on('live:started',d=>{syncRoomLiveStatus(d.roomId,d);if(d.roomId!==currentRoom)return;activeLive=d;liveTopicPlayback=d.topicPlayback||{playing:true,muted:false};liveLiked=false;renderLiveTitle();renderLiveTopic(d.topicMedia||null);if(isLiveChatActive())renderLiveChat(d.messages||[]);$('#liveStatus').textContent=`بث مباشر: ${d.displayName}`;if(!liveBroadcaster)$('#watchLiveBtn').classList.remove('hidden');updateLiveActionButtons();renderLiveParticipants();});
socket.on('live:status',d=>{if(d.active)syncRoomLiveStatus(d.roomId,d);if(d.roomId!==currentRoom)return;activeLive=d.active?d:null;if(d.active){liveTopicPlayback=d.topicPlayback||liveTopicPlayback;renderLiveTitle();renderLiveTopic(d.topicMedia||null);if(isLiveChatActive())renderLiveChat(d.messages||[]);$('#liveStatus').textContent=liveBroadcaster?(liveHost?'أنت تبث الآن':'أنت ضيف في البث'):`بث مباشر: ${d.displayName}`;if(!liveBroadcaster)$('#watchLiveBtn').classList.remove('hidden');}else if(!liveBroadcaster){syncRoomLiveStatus(d.roomId,null);renderLiveTitle();renderLiveTopic(null);liveLiked=false;liveWatching=false;liveMessages=[];setChatTitle('دردشة الساحة');$('#watchLiveBtn').classList.add('hidden');if(currentRoom)loadChat();}updateLiveActionButtons();renderLiveParticipants();});
socket.on('live:viewer',async d=>{if(!liveBroadcaster||d.roomId!==currentRoom||!liveStream)return;let pc=livePeers.get(d.viewerSocketId);if(pc)pc.close();pc=makePc('live',d.viewerSocketId,liveStream,e=>attachRemoteLive(d.viewerSocketId,e.streams[0]));livePeers.set(d.viewerSocketId,pc);await pc.setLocalDescription(await pc.createOffer());socket.emit('rtc:offer',{to:d.viewerSocketId,sdp:pc.localDescription,kind:'live',roomId:currentRoom});});
socket.on('live:viewer-left',d=>{if(d.roomId!==currentRoom)return;livePeers.get(d.viewerSocketId)?.close();livePeers.delete(d.viewerSocketId);removeLiveVideo(d.viewerSocketId);});
socket.on('live:force-ended',async d=>{if(d.roomId!==currentRoom)return;await cleanupForcedLive();toast(d.reason||'انتهى البث');});
socket.on('live:ended',async d=>{syncRoomLiveStatus(d.roomId,null);if(d.roomId!==currentRoom)return;activeLive=null;await cleanupForcedLive();$('#liveStatus').textContent='انتهى البث المباشر';});
socket.on('live:error',async d=>{toast(d.error);if(liveBroadcaster&&!activeLive){await cleanupForcedLive();$('#liveStatus').textContent='لا يوجد بث مباشر الآن';}});

socket.on('rtc:offer',async d=>{if(d.roomId!==currentRoom)return;if(d.kind==='voice'){const s=await ensureVoiceStream();let pc=voicePeers.get(d.from);if(!pc){pc=makePc('voice',d.from,s,e=>attachRemoteAudio(d.from,e.streams[0]));voicePeers.set(d.from,pc);}await pc.setRemoteDescription(d.sdp);await pc.setLocalDescription(await pc.createAnswer());socket.emit('rtc:answer',{to:d.from,sdp:pc.localDescription,kind:'voice',roomId:currentRoom});}else if(d.kind==='live'){if(liveBroadcaster){let pc=livePeers.get(d.from);if(!pc){pc=makePc('live',d.from,liveStream,e=>attachRemoteLive(d.from,e.streams[0]));livePeers.set(d.from,pc);}await pc.setRemoteDescription(d.sdp);await pc.setLocalDescription(await pc.createAnswer());socket.emit('rtc:answer',{to:d.from,sdp:pc.localDescription,kind:'live',roomId:currentRoom});}else{let pc=liveViewerPeers.get(d.from);if(pc)pc.close();pc=makePc('live',d.from,null,e=>{attachRemoteLive(d.from,e.streams[0]);$('#liveStatus').textContent='مشاهدة البث المباشر';});liveViewerPeers.set(d.from,pc);await pc.setRemoteDescription(d.sdp);await pc.setLocalDescription(await pc.createAnswer());socket.emit('rtc:answer',{to:d.from,sdp:pc.localDescription,kind:'live',roomId:currentRoom});}}});
socket.on('rtc:answer',async d=>{const pc=d.kind==='voice'?voicePeers.get(d.from):livePeers.get(d.from);if(pc)await pc.setRemoteDescription(d.sdp);});
socket.on('rtc:ice',async d=>{const pc=d.kind==='voice'?voicePeers.get(d.from):(liveBroadcaster?livePeers.get(d.from):liveViewerPeers.get(d.from));if(pc&&d.candidate){try{await pc.addIceCandidate(d.candidate);}catch{}}});
socket.on('voice:monitor-peer',async d=>{if(d.roomId!==currentRoom||!voiceStream)return;try{await createVoiceOffer(d.monitorSocketId);}catch{}});

function renderVoiceParticipants(){const canMod=canModerateCurrentRoom();$('#voiceParticipants').innerHTML=voiceParticipants.map(p=>`<div class="participant"><span class="miniAvatar">${esc((p.user?.displayName||p.user?.username||'م').slice(0,1))}</span><div class="meta"><b>${esc(p.user?.displayName||p.user?.username||'مستخدم')}</b><small>${p.role==='owner'?'مالك الغرفة':p.role==='moderator'?'مشرف الغرفة':p.muted?'مكتوم':'متحدث'}</small></div>${canMod&&p.socketId!==socket.id?`<div class="miniActions"><button data-action="mute" data-socket="${esc(p.socketId)}">كتم</button><button class="danger" data-action="kick" data-socket="${esc(p.socketId)}">إخراج</button></div>`:''}</div>`).join('');document.querySelectorAll('#voiceParticipants [data-action]').forEach(btn=>btn.onclick=()=>socket.emit('voice:moderate',{token,roomId:currentRoom,targetSocketId:btn.dataset.socket,action:btn.dataset.action}));}
socket.on('voice:participants',d=>{if(d.roomId!==currentRoom)return;voiceParticipants=d.participants||[];$('#voiceCount').textContent=voiceParticipants.length;renderVoiceParticipants();});
socket.on('voice:force-mute',()=>{if(!voiceStream)return;voiceMuted=true;voiceStream.getAudioTracks().forEach(t=>t.enabled=false);$('#muteBtn').textContent='فتح الميكروفون';toast('تم كتم ميكروفونك بواسطة مشرف الغرفة');});
socket.on('voice:kicked',async d=>{await leaveVoice();toast(d.reason||'تم إخراجك من الغرفة الصوتية');});
function resetRealtimeUi(){voiceParticipants=[];liveViewers=[];liveLiked=false;$('#voiceCount').textContent='0';renderVoiceParticipants();if(!voiceStream){$('#voiceStatus').textContent=currentRoom?'غير متصل':'اختر ساحة أولًا';$('#joinVoiceBtn').classList.remove('hidden');}activeLive=null;renderLiveTitle();renderLiveTopic(null);$('#watchLiveBtn').classList.add('hidden');$('#inviteGuestBtn').classList.add('hidden');$('#leaveGuestBtn').classList.add('hidden');$('#stopLiveBtn').classList.add('hidden');updateLiveActionButtons();renderLiveParticipants();setTimeout(requestLiveStatus,0);}
function updateAuthUI(){const yes=!!me;$('#composer').classList.toggle('hidden',!canAct());$('#newRoomBtn').classList.toggle('hidden',!canAct());$('#loginBtn').classList.toggle('hidden',yes);$('#adminPageBtn').classList.toggle('hidden',!yes||!isAdmin());$('#messagesBtn').classList.toggle('hidden',!yes);$('#notificationsBtn').classList.toggle('hidden',!yes);$('#profileBtn').classList.toggle('hidden',!yes);$('#logoutBtn').classList.toggle('hidden',!yes);$('#composerAvatar').textContent=(me?.displayName||me?.username||'أ').slice(0,1);if(currentRoom)$('#chatSend').classList.toggle('hidden',!canAct()||currentRoomPower.banned);if(yes)refreshSocialBadge();applyLanguage();updateLiveActionButtons();renderRooms();}
async function loadRoomMembers(){if(!currentRoom||!canModerateCurrentRoom())return;try{const list=await api(`/api/rooms/${currentRoom}/members`);$('#memberList').innerHTML=list.length?list.map(m=>`<div class="memberRow" data-user="${esc(m.userId)}"><div><b>${esc(m.displayName||m.username)}</b><small>@${esc(m.username)} · ${m.role==='moderator'?'مشرف':'عضو'} · ${m.status==='banned'?'محظور':'نشط'}</small></div><div class="inline"><button class="toggleRole">${m.role==='moderator'?'جعله عضوًا':'تعيين مشرف'}</button><button class="toggleBan">${m.status==='banned'?'إلغاء الحظر':'حظر'}</button><button class="removeMember danger">إزالة</button></div></div>`).join(''):'<div class="empty">لا يوجد أعضاء مضافون بعد.</div>';document.querySelectorAll('.memberRow').forEach(row=>{const member=list.find(x=>x.userId===row.dataset.user);row.querySelector('.toggleRole').onclick=()=>patchRoomMember(member.userId,{role:member.role==='moderator'?'member':'moderator'});row.querySelector('.toggleBan').onclick=()=>patchRoomMember(member.userId,{status:member.status==='banned'?'active':'banned'});row.querySelector('.removeMember').onclick=()=>removeRoomMember(member.userId);});}catch(e){toast(e.message);}}
async function openRoomManager(){if(!canModerateCurrentRoom())return;const room=rooms.find(r=>r.id===currentRoom);$('#manageRoomTitle').textContent=`إدارة: ${room?.name||''}`;$('#openRoomBtn').classList.toggle('hidden',!currentRoomPower.canManage);$('#closeRoomBtn').classList.toggle('hidden',!currentRoomPower.canManage);$('#roomManageModal').classList.remove('hidden');await loadRoomMembers();}
async function patchRoomMember(userId,body){try{await api(`/api/rooms/${currentRoom}/members/${userId}`,{method:'PATCH',body:JSON.stringify(body)});await loadRoomMembers();toast('تم تحديث الصلاحية');}catch(e){toast(e.message);}}
async function removeRoomMember(userId){if(!confirm('إزالة هذا العضو من قائمة الغرفة؟'))return;try{await api(`/api/rooms/${currentRoom}/members/${userId}`,{method:'DELETE'});await loadRoomMembers();toast('تمت الإزالة');}catch(e){toast(e.message);}}
async function setRoomStatus(status){try{await api(`/api/rooms/${currentRoom}/status`,{method:'PATCH',body:JSON.stringify({status})});currentRoomPower.roomStatus=status;toast(status==='closed'?'تم إغلاق الغرفة':'تم فتح الغرفة');await refreshRooms();}catch(e){toast(e.message);}}

function openModal(){authMode='login';renderAuthModal();$('#modal').classList.remove('hidden');$('#authName').focus();} function renderAuthModal(){const r=authMode==='register';$('#modalTitle').textContent=r?'إنشاء حساب':'تسجيل الدخول';$('#displayName').classList.toggle('hidden',!r);$('#authSubmit').textContent=r?'إنشاء الحساب':'دخول';$('#switchAuth').textContent=r?'لدي حساب بالفعل':'إنشاء حساب جديد';$('#authError').textContent='';}
$('#loginBtn').onclick=openModal;
$('#closeModal').onclick=()=>$('#modal').classList.add('hidden');
$('#switchAuth').onclick=()=>{authMode=authMode==='login'?'register':'login';renderAuthModal();};
$('#authSubmit').onclick=async()=>{try{const body={username:$('#authName').value.trim(),password:$('#authPass').value};if(authMode==='register')body.displayName=$('#displayName').value.trim();const r=await api(`/api/${authMode==='register'?'register':'login'}`,{method:'POST',body:JSON.stringify(body)});token=r.token;me=r.user;localStorage.setItem('token',token);syncSocketAuth();$('#modal').classList.add('hidden');updateAuthUI();await loadFeed();toast(`مرحبًا ${me.displayName}`);}catch(e){$('#authError').textContent=e.message;}};
$('#adminPageBtn').addEventListener('click',()=>{location.href='/admin';});
$('#manageRoomBtn').onclick=openRoomManager;$('#closeRoomManage').onclick=()=>$('#roomManageModal').classList.add('hidden');$('#addMemberBtn').onclick=async()=>{const username=$('#memberUsername').value.trim();if(!username)return;try{await api(`/api/rooms/${currentRoom}/members`,{method:'POST',body:JSON.stringify({username,role:$('#memberRole').value})});$('#memberUsername').value='';await loadRoomMembers();toast('تمت إضافة العضو');}catch(e){toast(e.message);}};$('#openRoomBtn').onclick=()=>setRoomStatus('active');$('#closeRoomBtn').onclick=()=>setRoomStatus('closed');
$('#newRoomBtn').onclick=()=>openRoomForm();
$('#saveRoomBtn').onclick=saveRoom;
$('#cancelRoomBtn').onclick=()=>{$('#roomForm').classList.add('hidden');roomEditId='';pendingRoomSource=null;};
function logout(refresh=true){leaveVoice();if(liveHost)stopLive();else if(liveBroadcaster)leaveLiveGuest();token='';me=null;localStorage.removeItem('token');updateAuthUI();if(refresh)loadFeed();} $('#logoutBtn').onclick=()=>logout();
$('#homeBtn').onclick=async()=>{if(liveHost)return toast('أنت تبث الآن. أنهِ البث قبل العودة للرئيسية حتى لا ينقطع الحوار.');await leaveVoice();await stopWatchingLive();currentRoom='';currentRoomPower={role:'guest',canModerate:false,canManage:false,banned:false,roomStatus:'active'};$('#manageRoomBtn').classList.add('hidden');resetRealtimeUi();$('#roomTitle').textContent=t('allRooms');$('#roomDesc').textContent='منشورات سياسية، صوت مباشر، صور وفيديو، وبث حي.';renderRooms();$('#globalChannels')?.classList.remove('hidden');$('#chatNotice').textContent='اختر ساحة لفتح الدردشة.';$('#chatBox').innerHTML='';$('#chatSend').classList.add('hidden');await loadChannelHome();await loadFeed();await loadPoliticalNews();};
function userLine(user){return `<button class="userLine" data-user="${esc(user.id)}">${avatarHtml(user)}<span><b>${esc(user.displayName||user.username)}</b><small>@${esc(user.username||'')}</small></span></button>`;}
async function refreshSocialBadge(){if(!me)return;try{socialSummary=await api('/api/me/social');const unread=(socialSummary.notifications||[]).filter(n=>!n.readAt).length+(socialSummary.requests||[]).length;$('#notificationCount').textContent=unread;$('#notificationCount').classList.toggle('hidden',!unread);}catch{}}
function renderNotificationList(notifications=[]){$('#notificationsList').innerHTML=notifications.length?notifications.map(n=>`<div class="msg ${n.readAt?'':'unread'}"><b>${esc(n.text)}</b><small class="time">${fmt(n.createdAt)}</small></div>`).join(''):'<div class="empty">لا توجد تنبيهات.</div>';}
async function loadSocialModal(){if(!me)return openModal();try{socialSummary=await api('/api/me/social');const requests=socialSummary.requests||[],notifications=socialSummary.notifications||[],followers=socialSummary.followers||[],following=socialSummary.following||[];$('#messageRequestsList').innerHTML=requests.length?requests.map(r=>`<div class="socialRow">${userLine(r.user)}<div class="miniActions"><button class="acceptMessageRequest" data-id="${esc(r.id)}">قبول</button><button class="rejectMessageRequest danger" data-id="${esc(r.id)}">رفض</button></div></div>`).join(''):'<div class="empty">لا توجد طلبات.</div>';renderNotificationList(notifications);$('#followersList').innerHTML=followers.length?followers.map(userLine).join(''):'<div class="empty">لا يوجد متابعون بعد.</div>';$('#followingList').innerHTML=following.length?following.map(userLine).join(''):'<div class="empty">لا تتابع أحدًا بعد.</div>';$('#socialModal').classList.remove('hidden');document.querySelectorAll('.userLine').forEach(b=>b.onclick=()=>openProfile(b.dataset.user));document.querySelectorAll('.acceptMessageRequest').forEach(b=>b.onclick=()=>respondMessageRequest(b.dataset.id,true));document.querySelectorAll('.rejectMessageRequest').forEach(b=>b.onclick=()=>respondMessageRequest(b.dataset.id,false));await api('/api/notifications/read',{method:'POST'});refreshSocialBadge();}catch(e){toast(e.message);}}
async function runSocialSearch(){const q=$('#socialUserSearch').value.trim();if(q.length<2)return toast('اكتب حرفين على الأقل');try{const users=await api(`/api/users/search?q=${encodeURIComponent(q)}`);$('#socialSearchResults').innerHTML=users.length?users.map(u=>`<div class="socialRow socialResult" data-user="${esc(u.id)}">${userLine(u)}<div class="miniActions"><button class="socialFollow primary" data-user="${esc(u.id)}">متابعة</button><button class="socialMessage" data-user="${esc(u.id)}">طلب مراسلة</button><button class="socialProfile" data-user="${esc(u.id)}">البروفايل</button></div></div>`).join(''):'<div class="empty">لا يوجد مستخدمون بهذا الاسم.</div>';document.querySelectorAll('#socialSearchResults .userLine,.socialProfile').forEach(b=>b.onclick=()=>openProfile(b.dataset.user||b.closest('.socialResult')?.dataset.user));document.querySelectorAll('.socialFollow').forEach(b=>b.onclick=async()=>{try{const s=await api(`/api/users/${b.dataset.user}/follow`,{method:'POST'});b.textContent=s.following?'تمت المتابعة':'متابعة';toast(s.following?'تمت المتابعة':'تم إلغاء المتابعة');await loadSocialModal();}catch(e){toast(e.message);}});document.querySelectorAll('.socialMessage').forEach(b=>b.onclick=async()=>{try{await api(`/api/users/${b.dataset.user}/message-request`,{method:'POST'});b.textContent='تم إرسال الطلب';b.disabled=true;toast('تم إرسال طلب المراسلة');await refreshSocialBadge();}catch(e){toast(e.message);}});}catch(e){toast(e.message);}}
async function respondMessageRequest(id,accept){try{await api(`/api/message-requests/${id}/respond`,{method:'POST',body:JSON.stringify({accept})});toast(accept?'تم قبول المراسلة':'تم رفض المراسلة');await loadSocialModal();}catch(e){toast(e.message);}}
async function toggleFollowProfile(){if(!profileUserId)return;try{const s=await api(`/api/users/${profileUserId}/follow`,{method:'POST'});$('#followUserBtn').textContent=s.following?'إلغاء المتابعة':'متابعة';$('#profileStats').textContent=`${s.followers||0} متابع · ${s.followingCount||0} يتابع`;toast(s.following?'تمت المتابعة':'تم إلغاء المتابعة');}catch(e){toast(e.message);}}
async function requestProfileMessage(){if(!profileUserId)return;try{await api(`/api/users/${profileUserId}/message-request`,{method:'POST'});$('#requestMessageBtn').textContent='تم إرسال الطلب';$('#requestMessageBtn').disabled=true;toast('تم إرسال طلب المراسلة');}catch(e){toast(e.message);}}
async function loadConversations(){if(!me)return openModal();try{const list=await api('/api/me/conversations');$('#conversationList').innerHTML=list.length?list.map(c=>`<button class="conversationItem" data-user="${esc(c.user.id)}" data-name="${esc(c.user.displayName||c.user.username)}">${avatarHtml(c.user)}<span><b>${esc(c.user.displayName||c.user.username)}</b><small>${esc(c.lastText||'مراسلة مقبولة')}</small></span></button>`).join(''):'<div class="empty">لا توجد مراسلات مقبولة بعد. افتح بروفايل مستخدم وأرسل طلب مراسلة.</div>';document.querySelectorAll('.conversationItem').forEach(b=>b.onclick=()=>openMessages(b.dataset.user,b.dataset.name));}catch(e){toast(e.message);}}
async function openMessages(userId=profileUserId,name=''){if(!me)return openModal();$('#messagesModal').classList.remove('hidden');await loadConversations();if(!userId){currentMessageUserId='';$('#messagesTitle').textContent='المراسلة';$('#directMessages').innerHTML='<div class="empty">اختر محادثة مقبولة من الأعلى.</div>';return;}currentMessageUserId=userId;$('#messagesTitle').textContent=name?`مراسلة ${name}`:'المراسلة';try{const list=await api(`/api/messages/${userId}`);$('#directMessages').innerHTML=list.length?list.map(m=>`<div class="msg ${m.fromUserId===me?.id?'mine':''}"><b>${esc(m.author?.displayName||m.author?.username||'مستخدم')}</b><div>${esc(m.text)}</div><small class="time">${fmt(m.createdAt)}</small></div>`).join(''):'<div class="empty">ابدأ المحادثة برسالة.</div>';$('#directMessages').scrollTop=$('#directMessages').scrollHeight;}catch(e){toast(e.message);}}
async function sendDirectMessage(){const text=$('#directMessageInput').value.trim();if(!text||!currentMessageUserId)return;try{await api(`/api/messages/${currentMessageUserId}`,{method:'POST',body:JSON.stringify({text})});$('#directMessageInput').value='';await openMessages(currentMessageUserId,$('#messagesTitle').textContent.replace(/^مراسلة\s*/,''));}catch(e){toast(e.message);}}
async function openProfile(userId=me?.id){if(!userId)return;try{const user=await api(`/api/users/${userId}/profile`), posts=await api(`/api/users/${userId}/posts`), own=me?.id===user.id;profileUserId=user.id;$('#profileTitle').textContent=user.displayName||user.username;$('#profileBioView').textContent=user.bio||'لا توجد نبذة بعد.';$('#profileAvatar').outerHTML=user.avatarUrl?`<img class="profileAvatar" id="profileAvatar" src="${esc(user.avatarUrl)}" alt="${esc(user.displayName||user.username)}">`:`<span class="profileAvatar" id="profileAvatar">${esc((user.displayName||user.username||'م').slice(0,1))}</span>`;$('#profileForm').classList.toggle('hidden',!own);$('#profileActions').classList.toggle('hidden',own||!me);$('#profileStats').textContent='';if(own){$('#profileName').value=me.displayName||'';$('#profileBio').value=me.bio||'';$('#currentPassword').value='';$('#newPassword').value='';}else if(me){const s=await api(`/api/users/${user.id}/social`);const accepted=s.messageRequest?.status==='accepted',pending=s.messageRequest?.status==='pending';$('#profileStats').textContent=`${s.followers||0} متابع · ${s.followingCount||0} يتابع`;$('#followUserBtn').textContent=s.following?'إلغاء المتابعة':'متابعة';$('#requestMessageBtn').textContent=accepted?'مسموح بالمراسلة':pending?'تم إرسال الطلب':'طلب مراسلة';$('#requestMessageBtn').disabled=accepted||pending;$('#openMessagesBtn').classList.toggle('hidden',!accepted);}$('#profilePosts').innerHTML=posts.length?posts.map(postHtml).join(''):'<div class="empty">لا توجد منشورات بعد.</div>';$('#profileModal').classList.remove('hidden');wirePosts();}catch(e){toast(e.message);}}
async function saveProfile(){if(!me)return;try{const body={displayName:$('#profileName').value.trim(),bio:$('#profileBio').value.trim()};if($('#newPassword').value){body.currentPassword=$('#currentPassword').value;body.newPassword=$('#newPassword').value;}me=await api('/api/me',{method:'PATCH',body:JSON.stringify(body)});const file=$('#profileImage').files?.[0];if(file){const fd=new FormData();fd.append('avatar',file);me=await api('/api/me/avatar',{method:'POST',body:fd});$('#profileImage').value='';}updateAuthUI();await loadFeed();await openProfile(me.id);toast('تم تحديث البروفايل');}catch(e){toast(e.message);}}
$('#profileBtn').onclick=()=>openProfile(me?.id);
$('#closeProfile').onclick=()=>$('#profileModal').classList.add('hidden');
$('#saveProfileBtn').onclick=saveProfile;
$('#notificationsBtn').onclick=loadSocialModal;
$('#messagesBtn').onclick=()=>openMessages('');
$('#closeSocial').onclick=()=>$('#socialModal').classList.add('hidden');
$('#socialSearchBtn').onclick=runSocialSearch;
$('#socialUserSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();runSocialSearch();}};
$('#closeMessages').onclick=()=>$('#messagesModal').classList.add('hidden');
$('#followUserBtn').onclick=toggleFollowProfile;
$('#requestMessageBtn').onclick=requestProfileMessage;
$('#openMessagesBtn').onclick=()=>openMessages(profileUserId,$('#profileTitle').textContent);
$('#sendDirectMessageBtn').onclick=sendDirectMessage;
$('#directMessageInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendDirectMessage();}};
async function runSearch(){currentSearch=$('#searchInput').value.trim();$('#clearSearchBtn').classList.toggle('hidden',!currentSearch);await loadFeed();} $('#searchBtn').onclick=runSearch;$('#searchInput').onkeydown=e=>{if(e.key==='Enter')runSearch();};$('#clearSearchBtn').onclick=async()=>{currentSearch='';$('#searchInput').value='';$('#clearSearchBtn').classList.add('hidden');await loadFeed();};
window.addEventListener('beforeunload',e=>{if(liveHost||liveBroadcaster){e.preventDefault();e.returnValue='';}});
